import{Ut as e,_t as t,at as n,et as r,it as i,n as a,rt as o}from"./chunks/framework.uM88Qy9F.js";var s=JSON.parse(`{"title":"消息通知","description":"","frontmatter":{},"headers":[],"relativePath":"backend/messaging.md","filePath":"backend/messaging.md","lastUpdated":1794049926000}`),c={name:`backend/messaging.md`};function l(a,s,c,l,u,d){return t(),o(`div`,null,[s[5]||=i(`<h1 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to “消息通知”">​</a></h1><p>本页说明站内通知与收件箱、消息模板、邮件与短信、群机器人与 Telegram 机器人，适用于后端开发者与运营配置人员。</p><p>Notification 包（Tier 2）负责以上全部。推送到浏览器经 Realtime 包的 <code>IRealtimePush</code>，见<a href="./realtime">实时推送</a>。</p><h2 id="站内通知" tabindex="-1">站内通知 <a class="header-anchor" href="#站内通知" aria-label="Permalink to “站内通知”">​</a></h2><h3 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to “通知”">​</a></h3><p><code>SysNotification</code>（租户库实体）：标题、正文（<code>Text</code> / <code>Markdown</code> / <code>Html</code>）、类型（<code>System</code>、<code>Security</code>、<code>Business</code>、<code>Todo</code>、<code>Emergency</code>）、优先级（<code>Low</code>、<code>Normal</code>、<code>High</code>、<code>Urgent</code>）、图标、链接、业务类型与 ID、投递渠道、目标、展示方式与生效 / 到期时间。HTML 正文渲染前净化：去掉脚本、事件处理器、<code>javascript:</code> 链接、<code>&lt;style&gt;</code> 与表单控件，行内样式保留。</p><table tabindex="0"><thead><tr><th>维度</th><th>取值</th></tr></thead><tbody><tr><td>目标</td><td><code>All</code>、<code>Role</code>、<code>Department</code>（含下级）、<code>User</code>；接收人经 <code>Contracts</code> 的 <code>IRecipientSource</code> 解析，再按接收人的通知偏好过滤</td></tr><tr><td>展示</td><td>普通、横幅（<code>IsBanner</code>）、弹窗（<code>IsPopup</code>）</td></tr><tr><td>阅读</td><td>需确认（<code>NeedConfirm</code>）、强制阅读（<code>IsMandatory</code>，路由守卫据此拦截）</td></tr><tr><td>渠道</td><td>站内之外可同时发邮件、短信、机器人</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>notifications.list</code> / <code>get</code> / <code>read-stats</code> / <code>recipients</code></td><td><code>notification.notifications.read</code></td><td>阅读统计、接收人与阅读确认状态</td></tr><tr><td><code>notifications.create</code> / <code>update</code> / <code>delete</code></td><td><code>notification.notifications.create</code> / <code>update</code> / <code>delete</code></td><td>缺省存草稿；<code>publishImmediately</code> 另要发布权限</td></tr><tr><td><code>notifications.publish</code></td><td><code>notification.notifications.publish</code></td><td>解析接收人、写收件箱，提交后按人推 <code>ReceiveNotification</code>，并按渠道入队；进度经 <code>TaskProgress</code> 推给发布人（见<a href="./realtime#任务进度">任务进度</a>）</td></tr><tr><td><code>notifications.remind</code></td><td><code>notification.notifications.publish</code></td><td>再推给未读或未确认的接收人</td></tr></tbody></table><h3 id="收件箱-我的消息" tabindex="-1">收件箱（我的消息） <a class="header-anchor" href="#收件箱-我的消息" aria-label="Permalink to “收件箱（我的消息）”">​</a></h3><p><code>SysUserNotification</code> 是按人的投递记录。全部是自助操作（只要求登录）：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>inbox.list</code></td><td>我的消息页与顶栏通知中心</td></tr><tr><td><code>inbox.banners</code> / <code>inbox.popups</code> / <code>inbox.mandatory</code></td><td>未读横幅、还没弹过的弹窗、待强制阅读</td></tr><tr><td><code>inbox.mark-read</code> / <code>mark-all-read</code> / <code>confirm</code> / <code>mark-popup-shown</code></td><td>已读、全部已读、确认、弹窗已展示</td></tr><tr><td><code>inbox.delete</code></td><td>删除自己的投递</td></tr></tbody></table><p>别的包直接给某些人投递站内信（工作流的待办、Identity 的安全提醒）经 <code>Contracts</code> 的 <code>IInboxDelivery</code>。</p><h2 id="消息模板" tabindex="-1">消息模板 <a class="header-anchor" href="#消息模板" aria-label="Permalink to “消息模板”">​</a></h2>`,13),r(`p`,null,[s[0]||=r(`code`,null,`SysMessageTemplate`,-1),s[1]||=n(`（平台库实体，`,-1),s[2]||=r(`code`,null,`IOwnedByTenant`,-1),s[3]||=n(`）：编码、渠道、主题、正文、是否 HTML、变量说明。模板引擎是 Scriban，变量写作 `,-1),r(`code`,null,e(a.name),1),s[4]||=n(`。`,-1)]),s[6]||=i(`<table tabindex="0"><thead><tr><th>渠道</th><th>主题</th><th>HTML</th></tr></thead><tbody><tr><td><code>Email</code></td><td>有</td><td>有</td></tr><tr><td><code>InApp</code> 站内通知</td><td>有（作通知标题）</td><td>—</td></tr><tr><td><code>Sms</code></td><td>—</td><td>—</td></tr><tr><td><code>Bot</code></td><td>—</td><td>—</td></tr></tbody></table><ul><li>租户优先、平台回退：发送时先找当前一侧启用的同编码模板，再找平台的；都没有即该渠道不可用。</li><li>租户的模板列表同时列出平台模板（<code>isPlatform</code>），平台模板对租户只读（改删给 <code>NOTIFICATION_DENIED_002</code>），新建同编码即覆盖。</li><li>平台种子 <code>notification.templates</code> 写 9 个，只首写：登录验证码邮件与短信、验证码（绑定 / 换绑 / 两步验证）邮件与短信、重置密码邮件、注册欢迎邮件、系统通知的邮件与短信，以及机器人消息 <code>notification-bot</code>（变量 <code>title / content / link / brand</code>）。<code>brand</code> 取 <code>BasicApp:Notification:Brand</code>，不写即应用名。</li><li>模板不加载别的文件，循环与递归有上限，语法树限深（<code>TemplateLimits</code>，保存与渲染前都判），一次渲染最多 5 秒；HTML 模板里的参数值先做 HTML 编码。</li></ul><p>操作 <code>message-templates.list / get / create / update / delete</code>，权限 <code>notification.message-templates.*</code>。</p><h2 id="邮件与短信" tabindex="-1">邮件与短信 <a class="header-anchor" href="#邮件与短信" aria-label="Permalink to “邮件与短信”">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>实体</th><th>操作 / 权限</th><th>说明</th></tr></thead><tbody><tr><td>邮件</td><td><code>SysEmailConfig</code></td><td><code>email-configs.*</code> / <code>notification.email-configs.*</code></td><td>SMTP（MailKit），多通道、<code>set-default</code> 设缺省通道；连接过<a href="./../configuration#xihan-security-outbound">出站地址策略</a>，内网中继要放行</td></tr><tr><td>短信</td><td><code>SysSmsConfig</code></td><td><code>sms-configs.*</code> / <code>notification.sms-configs.*</code></td><td>阿里云（Dysmsapi）、腾讯云，直接签名调用、不引 SDK；模板编码到服务商模板的映射在配置里登记</td></tr></tbody></table><ul><li>租户没有可用通道时回落平台的配置（平台代发）；机器人不回落。</li><li>密钥经 <code>ISecretProtector</code> 加密存放，不回显。</li><li>发送记录 <code>SysEmail</code> / <code>SysSms</code> 本身即发件箱：<code>emails.list / get / resend / cancel / delete</code>、<code>sms.*</code> 同（权限 <code>notification.emails.read / resend / delete</code>，<code>cancel</code> 用 <code>resend</code>；短信同理）。验证码（业务类型 <code>identity.verification</code>）的记录不返回正文与参数，发送结束即清空，也不能重发：读记录的权限不能拿它接管账号。</li><li>改通道的地址（SMTP 的主机、端口，关掉加密或不再验证书）时，留空的口令不再保留，要重新填（<code>NOTIFICATION_VALIDATION_016</code>）。AI 提供商的地址（<code>AI_VALIDATION_107</code>）、代码生成数据源的地址（<code>CODEGENERATION_VALIDATION_014</code>）同样。</li><li>发送循环按 <code>BasicApp:Notification</code> 的 <code>DispatchInterval</code>、<code>RetryDelay</code>、<code>MaxAttempts</code>、<code>StuckAfter</code> 工作；启动时把上个进程发到一半的记录改回排队中。</li></ul><p>身份相关的发码（验证码登录、换绑、双因素）经 <code>Contracts</code> 的 <code>IMessageSender</code> 按模板入队。</p><h2 id="群机器人" tabindex="-1">群机器人 <a class="header-anchor" href="#群机器人" aria-label="Permalink to “群机器人”">​</a></h2><p><code>SysBotConfig</code>：钉钉、飞书、企业微信群机器人的 Webhook（含签名密钥），两侧都能配，多个、每个服务商可设缺省。通知选了机器人渠道时按模板 <code>notification-bot</code> 渲染，给本侧每个服务商的缺省机器人各写一条；平台一侧另给每个启用的 Telegram 机器人的广播群各写一条。发送记录 <code>SysBotMessage</code> 与邮件短信走同一个发件箱与发送循环。</p><p>Webhook 地址带凭据：经 <code>ISecretProtector</code> 加密存放，响应只给主机（<code>https://oapi.dingtalk.com/***</code>），修改时交回这个值即保留原地址；差异日志打码，请求日志不记。解不开（数据保护密钥变了，或是没加密的数据）时不当明文用：响应只给 <code>***</code>，发送失败并在发送记录里写明原因，交回遮过的值报 503 <code>NOTIFICATION_UNAVAILABLE_004</code>，重新填完整地址即恢复。</p><p>操作 <code>bot-configs.list / get / create / update / set-default / delete</code>，权限 <code>notification.bot-configs.*</code>。</p><h2 id="telegram-机器人" tabindex="-1">Telegram 机器人 <a class="header-anchor" href="#telegram-机器人" aria-label="Permalink to “Telegram 机器人”">​</a></h2><p><code>SysTelegramBot</code>：平台托管（权限码只在平台一侧），多个机器人实例，令牌加密存储、不回显，带管理员、群组白名单、命令白名单与广播群。</p><ul><li>平台的系统参数 <code>notification.telegram</code>（JSON）管总开关（缺省关）、Webhook 对外根地址、刷新周期与网络（代理、Bot API 根地址、超时），运行中改了下一个刷新周期生效；自建 Bot API Server 的主机要在 <code>XiHan:Security:Outbound:AllowedHosts</code> 放行。</li><li>配了 Webhook 根地址即走普通端点 <code>POST /api/telegram-bot/webhook/{botName}</code>，校验 secret token（加密参数 <code>notification.telegram.webhook-secret-token</code>）；没配即长轮询（<code>BasicApp:Notification:Telegram:PollingTimeoutSeconds</code>）。</li><li>交互按路由与守卫处理消息与回调，内置 <code>/start</code>、<code>/help</code>、<code>/myid</code>，可由处理器扩展；处理器登记有误（命令重复、正则写错）启动即失败。</li><li>出站发送带重试（<code>BasicApp:Notification:Telegram:Retry</code>），最终失败可私发管理员告警；回复文案在 <code>BasicApp:Notification:Telegram:Texts</code>。</li></ul><p>操作 <code>telegram-bots.list / get / create / update / delete</code>，权限 <code>notification.telegram-bots.*</code>。</p><h2 id="通知偏好" tabindex="-1">通知偏好 <a class="header-anchor" href="#通知偏好" aria-label="Permalink to “通知偏好”">​</a></h2><p>个人中心的 <code>profile.notification-preference</code> / <code>profile.update-notification-preference</code>（Identity）：按渠道与类别开关接收，两者都开着才收；没有设置过的用户缺省全收。偏好存在平台库，跟着账号走、不分租户；Notification 发布与扇出时经 <code>Contracts</code> 的 <code>INotificationPreferences</code> 过滤接收人。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to “页面”">​</a></h2><p><code>src/modules/notification</code>：我的消息（收件箱）、通知公告、消息模板、邮件短信（发送记录）、邮件配置、短信配置、机器人配置、Telegram 机器人。通知正文的格式为 Markdown 时用 Markdown 编辑器（<code>XMdEditor</code>），其余格式用文本框。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./realtime">实时推送</a> · <a href="./caching">缓存与异步</a> · <a href="./../frontend/realtime">前端实时通信</a></li></ul>`,21)])}var u=a(c,[[`render`,l]]);export{s as __pageData,u as default};